fn invalid_cell_histories_fail_the_gate() {
    // CONTRACT: docs/contracts/hot-path-attribution.md#HPA-01 and #HPA-12.
    let original = std::fs::read_to_string(workspace_file(LEDGER)).expect("ledger");
    for mutation in ["missing", "duplicate", "unknown", "invalid_sample"] {
        let mut value: toml::Value = toml::from_str(&original).expect("fixture TOML");
        let cells = value.get_mut("cells").and_then(toml::Value::as_array_mut).expect("cells");
        match mutation {
            "missing" => { cells.pop(); }
            "duplicate" => { cells.push(cells[0].clone()); }
            "unknown" => { cells[0]["id"] = toml::Value::String("unknown.cell".into()); }
            _ => {
                cells[0]["samples"] = toml::Value::Array(vec![toml::Value::Table(toml::map::Map::new())]);
            }
        }
        let text = toml::to_string(&value).expect("serialize mutation");
        assert!(parse_ledger(&text).is_err(), "gate accepted {mutation}");
    }

